<template><div class="sequence-viz-workspace" data-testid="sequence-v1" :data-species-id="speciesId" :data-omics="omics" :data-scope="scope" :data-section="section">
 <ModuleState v-if="error" state="error" title="Sequence visualizations unavailable" :message="error" :retry="reload"/><ModuleState v-else-if="!manifest" state="loading" title="Loading complete sequence visualizations"/>
 <section v-else-if="manifest.readiness!=='ready'" class="panel" data-testid="sequence-preparation"><h3>{{ manifest.readiness==='unavailable'?'Required source unavailable':'Preparing complete-population visualizations' }}</h3><p>{{ manifest.readiness }} · {{ manifest.error||manifest.reason_code||'All eligible records are calculated by the bounded worker. Results will refresh automatically.' }}</p><button class="btn subtle" @click="reload">Check availability / retry</button></section>
 <template v-else><section class="panel"><div class="section-header"><div><h3>{{ omics==='genome'?'Genome':'Transcript sequence' }} · {{ section==='basic'?'Basic visualization':'Deep analysis' }}</h3><p class="muted">{{ manifest.n_source.toLocaleString() }} complete {{ scope }} records · {{ manifest.fields.length }} numeric source fields · no row sampling</p></div><span class="badge">{{ manifest.method_version }}</span></div><p class="muted">Full supplements append missing columns under Core identity. Raw zeros, missing values and coding-specific eligibility retain separate meanings.</p></section>
 <div class="sequence-viz-grid"><template v-for="c in charts" :key="c.chart_id"><div :class="['sequence-viz-item',c.kind==='distribution_ecdf'?'sequence-viz-half':'sequence-viz-wide']">
  <div v-if="c.kind==='custom_pair'" class="sequence-viz-controls"><label>X field<select aria-label="X field" v-model="pairs[c.chart_id].x" class="input"><option v-for="f in pairFields" :key="f.key" :value="f.key">{{ f.key }}</option></select></label><label>Y field<select aria-label="Y field" v-model="pairs[c.chart_id].y" class="input"><option v-for="f in pairFields" :key="f.key" :value="f.key">{{ f.key }}</option></select></label><label>X transform<select v-model="pairs[c.chart_id].tx" class="input"><option>identity</option><option>log10</option><option>log1p</option></select></label><label>Y transform<select v-model="pairs[c.chart_id].ty" class="input"><option>identity</option><option>log10</option><option>log1p</option></select></label><label>Conditional groups<input v-model.number="pairs[c.chart_id].groups" class="input" type="number" min="1" max="20"/></label><button class="btn" @click="loadPair(c.chart_id)">Update this relationship</button></div>
  <div v-if="c.kind==='threshold_network'" class="sequence-viz-controls"><label>Absolute Spearman threshold {{ thresholds[c.chart_id] }}<input v-model.number="thresholds[c.chart_id]" type="range" min="0" max="0.95" step="0.05"/></label></div>
  <div v-if="c.kind==='core_quantile_signature'" class="sequence-viz-controls"><button class="btn subtle" :disabled="signaturePage===1" @click="signaturePage--">Previous 30 fields</button><span>Signature page {{ signaturePage }} / {{ Math.ceil(manifest.fields.length/30) }}</span><button class="btn subtle" :disabled="signaturePage*30>=manifest.fields.length" @click="signaturePage++">Next 30 fields</button></div>
  <SequenceFigure :figure="shownFigure(c.chart_id)" :chart-id="c.chart_id" :title="c.title" :species-id="speciesId" :omics="omics" :scope="scope" :loading="pairLoading[c.chart_id]||states[c.chart_id]?.loading" :error="pairErrors[c.chart_id]||states[c.chart_id]?.error" :threshold="thresholds[c.chart_id]" @bin="openBin"/>
 </div></template></div>
 <SequenceFieldAtlas v-if="section==='basic'" :key="omics+scope+manifest.artifact_version" :species-id="speciesId" :omics="omics" :scope="scope" :manifest="manifest"/>
 <template v-if="section==='deep'"><SequenceCoordinateAtlas v-if="omics==='genome'" :species-id="speciesId" :scope="scope" :manifest="manifest"/><SequenceCandidateTable :species-id="speciesId" :omics="omics" :scope="scope" :manifest="manifest"/><SequenceCohortSelector :species-id="speciesId" :omics="omics" :scope="scope" :manifest="manifest"/></template>
 <section v-if="selectedBin" class="panel" data-testid="sequence-members"><h3>Exact members · {{ selectedBin.chart_id }} · {{ selectedBin.bin_id }}</h3><div class="sequence-viz-controls"><button class="btn subtle" @click="closeMembers">Close members</button><button class="btn subtle" :disabled="memberPage===1" @click="memberPage--;loadMembers()">Previous</button><span>{{ members?.total||0 }} exact members · page {{ memberPage }}</span><button class="btn subtle" :disabled="memberPage*50>=(members?.total||0)" @click="memberPage++;loadMembers()">Next</button><a :href="memberDownload">All members CSV</a></div><p v-if="memberError">{{ memberError }}</p><div class="table-wrap"><table><thead><tr><th>Native record ID</th><th>Annotation</th></tr></thead><tbody><tr v-for="r in members?.rows||[]" :key="r.entity_id"><td><button class="sequence-viz-entity" @click="openEntity(r)">{{ r.entity_id }}</button></td><td>{{ r.gene_name||r.gene_symbol||r.biotype||r.transcript_biotype }}</td></tr></tbody></table></div></section>
 </template></div></template>
<script setup>
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';import ModuleState from '../ModuleState.vue';import SequenceFigure from './SequenceFigure.vue';import SequenceFieldAtlas from './SequenceFieldAtlas.vue';import SequenceCoordinateAtlas from './SequenceCoordinateAtlas.vue';import SequenceCandidateTable from './SequenceCandidateTable.vue';import SequenceCohortSelector from './SequenceCohortSelector.vue';import {useSequenceVisuals} from '../../composables/useSequenceVisuals';import {sequenceGet,sequenceExport} from '../../api/sequenceVisuals'
const props=defineProps({speciesId:String,omics:String,scope:{type:String,default:'core'},section:{type:String,default:'basic'}});const emit=defineEmits(['manifest']);const {manifest,states,error,reload}=useSequenceVisuals(props);const pairs=reactive({}),pairResults=reactive({}),pairLoading=reactive({}),pairErrors=reactive({}),thresholds=reactive({}),signaturePage=ref(1);const selectedBin=ref(null),members=ref(null),memberPage=ref(1),memberError=ref('');let memberController,memberSeq=0;const controllers=new Map(),sequences=new Map()
const pairFields=computed(()=>manifest.value?.catalog?.filter(c=>c.role==='numeric')||manifest.value?.fields||[])
const charts=computed(()=>manifest.value?.charts?.filter(c=>(c.section===props.section||(props.section==='deep'&&c.chart_id.includes('S')))&&!['complete_field_atlas','native_quantile_table','species_fingerprint_pca','species_distance','species_dispersion'].includes(c.kind))||[])
watch(manifest,m=>{if(!m)return;emit('manifest',m);for(const c of m.charts||[]){if(c.kind==='custom_pair')pairs[c.chart_id]={x:c.chart_id==='GB10'?'upstream_intergenic_bp':c.chart_id==='TD19'?'max_run_any':'gc_content',y:c.chart_id==='GB10'?'delta_gc_pp':c.chart_id==='TD19'?'nt_entropy':'protein_gravy',tx:c.chart_id==='GB10'?'log1p':c.chart_id==='TD19'?'log10':'identity',ty:'identity',groups:10};if(c.kind==='threshold_network')thresholds[c.chart_id]=.65}})
function shownFigure(id){const f=pairResults[id]||states[id]?.result;if(f?.data.kind==='core_quantile_signature')return {...f,data:{...f.data,rows:f.data.rows.slice((signaturePage.value-1)*30,signaturePage.value*30)}};return f}
async function loadPair(id){controllers.get(id)?.abort();const controller=new AbortController(),seq=(sequences.get(id)||0)+1;controllers.set(id,controller);sequences.set(id,seq);pairLoading[id]=true;pairErrors[id]='';const p=pairs[id];try{const r=await sequenceGet(props.speciesId,props.omics,'pair/',{scope:props.scope,artifact_version:manifest.value.artifact_version,source_hash:manifest.value.source_hash,x:p.x,y:p.y,transform_x:p.tx,transform_y:p.ty,groups:p.groups},{signal:controller.signal});if(sequences.get(id)===seq)pairResults[id]={...r.result,chart_id:id,title:states[id]?.result?.title}}catch(e){if(sequences.get(id)===seq&&!controller.signal.aborted)pairErrors[id]=e.message}finally{if(sequences.get(id)===seq)pairLoading[id]=false}}
const memberParams=computed(()=>selectedBin.value?{scope:props.scope,chart_id:selectedBin.value.chart_id,bin_id:selectedBin.value.bin_id,variant_id:selectedBin.value.variant_id||'',artifact_version:selectedBin.value.figure.artifact_version,source_hash:selectedBin.value.figure.source_hash}:{})
const memberDownload=computed(()=>sequenceExport(props.speciesId,props.omics,{...memberParams.value,kind:'members'}))
function openBin(raw){selectedBin.value=raw;members.value=null;memberPage.value=1;loadMembers()}
async function loadMembers(){const current=++memberSeq;memberController?.abort();memberController=new AbortController();try{const r=await sequenceGet(props.speciesId,props.omics,'members/',{...memberParams.value,page:memberPage.value,page_size:50},{signal:memberController.signal});if(current===memberSeq){members.value=r;memberError.value=''}}catch(e){if(current===memberSeq&&!memberController.signal.aborted)memberError.value=e.message}}
function closeMembers(){memberSeq++;memberController?.abort();selectedBin.value=null;members.value=null}
function openEntity(r){window.dispatchEvent(new CustomEvent('stoich-entity-chart-click',{detail:{...r,species_id:props.speciesId}}))}
function reset(){closeMembers();controllers.forEach(c=>c.abort());controllers.clear();sequences.forEach((s,k)=>sequences.set(k,s+1));for(const r of [pairResults,pairErrors,pairLoading,pairs,thresholds])Object.keys(r).forEach(k=>delete r[k]);signaturePage.value=1}
watch(()=>[props.speciesId,props.omics,props.scope,props.section],reset);onBeforeUnmount(reset)
</script>
<style>
.sequence-viz-workspace{display:flex;flex-direction:column;gap:22px;min-width:0;color:#18334a}.sequence-viz-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:22px}.sequence-viz-item{min-width:0;display:flex;flex-direction:column;gap:16px}.sequence-viz-wide{grid-column:1/-1}.sequence-viz-half{grid-column:span 6}.sequence-viz-half>.sequence-viz-figure{flex:1}.sequence-viz-figure{min-width:0;box-sizing:border-box}.sequence-viz-figure h3{font-size:18px;line-height:1.4;text-wrap:balance}.sequence-viz-scroll{max-width:100%;overflow:auto;background:white}.sequence-viz-workspace .chart-export-row{position:relative;inset:auto;justify-content:flex-end;min-height:28px;margin-bottom:8px}.sequence-viz-caption,.sequence-viz-method{font-size:12px;line-height:1.6;color:#526575;overflow-wrap:anywhere}.sequence-viz-method summary{cursor:pointer;color:#285d85}.sequence-viz-method pre{white-space:pre-wrap}.sequence-viz-downloads{display:flex;gap:10px 18px;flex-wrap:wrap;border-top:1px solid #dce4ea;padding-top:12px;font-size:12px}.sequence-viz-controls{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:14px 0;font-size:12px}.sequence-viz-controls label{display:flex;flex-direction:column;gap:6px;max-width:100%;min-width:140px}.sequence-viz-controls .input{max-width:100%;min-width:0}.sequence-viz-controls select{max-width:350px}.sequence-viz-controls input[type=number]{width:150px}.sequence-viz-controls .btn{white-space:normal;overflow-wrap:anywhere;max-width:100%}.sequence-viz-workspace .table-wrap{max-width:100%;overflow:auto}.sequence-viz-workspace table{font-size:12px}.sequence-viz-field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.sequence-viz-field-grid>section{min-width:0;border-top:1px solid #dce4ea;padding-top:12px}.sequence-viz-field-grid h4{font-size:14px;overflow-wrap:anywhere}.sequence-viz-entity{padding:0;background:none;border:0;font:inherit;color:#1f5d9a;text-decoration:underline;cursor:pointer;text-align:left;overflow-wrap:anywhere}.sequence-viz-entity:focus-visible{outline:2px solid #2867a1;outline-offset:4px}.sequence-viz-cohort{display:flex;flex-direction:column;gap:18px;min-width:0}.sequence-viz-matches{max-height:260px;overflow:auto;padding:0;list-style:none}.sequence-viz-workspace .section-header{gap:14px;align-items:start}.sequence-viz-workspace .muted{overflow-wrap:anywhere}
@media(max-width:1100px){.sequence-viz-half{grid-column:1/-1}}@media(max-width:700px){.sequence-viz-field-grid{grid-template-columns:1fr}.sequence-viz-workspace .panel{padding:16px}.sequence-viz-workspace .section-header{flex-wrap:wrap}.sequence-viz-controls label{flex:1 1 160px}.sequence-viz-controls select{max-width:100%}.sequence-viz-figure h3{font-size:16px}}
@media(prefers-reduced-motion:reduce){.sequence-viz-workspace *{animation:none!important;transition-duration:0ms!important}}
</style>
